<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
$db=saas_db();
$slug=trim((string)($_GET['slug']??''));
$token=trim((string)($_GET['token']??''));
if($slug===''||!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Ticket link is invalid.');}
$hash=hash('sha256',$token);
$q=$db->prepare("SELECT tp.id tp_id,tp.status,tp.fee,tp.discount,pp.full_name,pp.phone,t.id tour_id,t.name tour_name,t.slug,t.start_date,t.end_date,o.name organization_name,o.currency,ti.id ticket_id,ti.ticket_number,ti.status ticket_status,ti.template_key,ti.qr_token_hash,ti.issued_at FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id JOIN ticket_instances ti ON ti.tour_passenger_id=tp.id AND ti.status='ISSUED' WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND tp.status='ACTIVE' AND o.status='ACTIVE' ORDER BY ti.id DESC LIMIT 1");
$q->execute([$slug,$hash]);
$ticket=$q->fetch();
if(!$ticket){http_response_code(404);exit('Active ticket not found.');}
$q=$db->prepare("SELECT b.name bus_name,b.bus_number,s.seat_code FROM passenger_seat_assignments psa JOIN buses b ON b.id=psa.bus_id JOIN seats s ON s.id=psa.seat_id WHERE psa.tour_passenger_id=? LIMIT 1");$q->execute([(int)$ticket['tp_id']]);$seat=$q->fetch();
$q=$db->prepare("SELECT r.room_no,r.room_type FROM room_assignments ra JOIN rooms r ON r.id=ra.room_id WHERE ra.tour_passenger_id=? LIMIT 1");$q->execute([(int)$ticket['tp_id']]);$room=$q->fetch();
$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_id=? AND tour_passenger_id=?');$q->execute([(int)$ticket['tour_id'],(int)$ticket['tp_id']]);$paid=(float)$q->fetchColumn();
$total=max(0,(float)$ticket['fee']-(float)$ticket['discount']);$due=max(0,$total-$paid);$currency=$ticket['currency']?:'BDT';
$templates=['classic'=>'Classic','travel'=>'Travel','event'=>'Event'];
$template=strtolower(trim((string)($_GET['template']??$ticket['template_key']??'classic')));if(!isset($templates[$template]))$template='classic';
$saveError='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['template'])){try{saas_check_csrf();$new=strtolower(trim((string)$_POST['template']));if(!isset($templates[$new]))throw new RuntimeException('Invalid ticket design.');$q=$db->prepare("UPDATE ticket_instances SET template_key=?,updated_at=NOW() WHERE id=? AND tour_passenger_id=? AND status='ISSUED'");$q->execute([$new,(int)$ticket['ticket_id'],(int)$ticket['tp_id']]);$template=$new;saas_audit('public.ticket_template_changed','ticket_instance',(int)$ticket['ticket_id'],json_encode(['template'=>$new],JSON_UNESCAPED_UNICODE));}catch(Throwable $e){$saveError='Could not save the ticket design.';}}
$qrToken=bin2hex(random_bytes(32));
$q=$db->prepare('UPDATE ticket_instances SET qr_token_hash=?,qr_token_created_at=NOW(),qr_token_revoked_at=NULL,updated_at=NOW() WHERE id=? AND status=\'ISSUED\'');
$q->execute([hash('sha256',$qrToken),(int)$ticket['ticket_id']]);
$verifyUrl=rtrim((string)($_SERVER['REQUEST_SCHEME']??'https').'://'.(string)($_SERVER['HTTP_HOST']??''),'/').'/ticket_verify.php?ticket='.rawurlencode($ticket['ticket_number']).'&q='.rawurlencode($qrToken);
$qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=6&data='.rawurlencode($verifyUrl);
$accent=$template==='travel'?'#0b7a75':($template==='event'?'#7c3aed':'#155eef');$dark=$template==='travel'?'#073b3a':($template==='event'?'#2e1065':'#0f172a');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket <?=saas_h($ticket['ticket_number'])?></title><style>@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;background:#e5e7eb;font-family:Arial,sans-serif;color:#182230}.controls{max-width:900px;margin:18px auto;text-align:center}.controls select,.controls button{padding:10px 12px;border:1px solid #d0d5dd;border-radius:8px;background:#fff}.controls button{cursor:pointer}.ok{padding:8px;margin:8px}.ticket{width:297mm;height:118.8mm;position:relative;overflow:hidden;margin:20px auto;background:#fff;border:1px solid #d0d5dd}.top{height:30%;padding:18px 26px;background:linear-gradient(120deg,<?=saas_h($dark)?>,<?=saas_h($accent)?>);color:#fff}.top h1{margin:0;font-size:28px}.org{font-size:13px;opacity:.85}.body{height:70%;display:grid;grid-template-columns:1fr 210px;padding:18px 26px;gap:18px}.details{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{padding:8px 10px;border-bottom:1px dashed #d0d5dd}.label{font-size:10px;text-transform:uppercase;color:#667085}.value{font-size:16px;font-weight:700;margin-top:2px}.qr{display:flex;align-items:center;justify-content:center;border-left:1px dashed #98a2b3}.qr img{width:150px;height:150px}.status{position:absolute;right:25px;top:18px;padding:6px 10px;border-radius:999px;background:#ecfdf3;color:#067647;font-weight:800;font-size:12px}@media print{body{background:#fff}.controls{display:none}.ticket{margin:0;border:0}}@media(max-width:800px){.ticket{width:100%;height:auto;min-height:420px}.body{grid-template-columns:1fr}.qr{border-left:0;border-top:1px dashed #98a2b3;padding-top:15px}.details{grid-template-columns:1fr}}</style></head><body><div class="controls"><form method="post" style="display:inline-flex;gap:8px;align-items:center"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><label>Ticket design <select name="template"><option value="classic" <?=($template==='classic'?'selected':'')?>>Classic</option><option value="travel" <?=($template==='travel'?'selected':'')?>>Travel</option><option value="event" <?=($template==='event'?'selected':'')?>>Event</option></select></label><button type="submit">Save design</button></form> <button onclick="window.print()">Print Ticket</button><?php if($saveError):?><div class="ok"><?=saas_h($saveError)?></div><?php endif;?></div><main class="ticket"><section class="top"><div class="org"><?=saas_h($ticket['organization_name'])?></div><h1><?=saas_h($ticket['tour_name'])?></h1><div><?=saas_h($ticket['start_date']?:'Date TBA')?><?=($ticket['end_date']?' — '.saas_h($ticket['end_date']):'')?></div></section><span class="status">VALID TICKET</span><section class="body"><div><div class="details"><div class="field"><div class="label">Guest Name</div><div class="value"><?=saas_h($ticket['full_name'])?></div></div><div class="field"><div class="label">Phone</div><div class="value"><?=saas_h($ticket['phone'])?></div></div><div class="field"><div class="label">Bus</div><div class="value"><?=saas_h($seat['bus_name']??'Not assigned')?></div></div><div class="field"><div class="label">Bus Number</div><div class="value"><?=saas_h($seat['bus_number']??'—')?></div></div><div class="field"><div class="label">Seat</div><div class="value"><?=saas_h($seat['seat_code']??'Not assigned')?></div></div><div class="field"><div class="label">Room</div><div class="value"><?=saas_h($room['room_no']??'Not assigned')?><?=($room?' · '.saas_h($room['room_type']):'')?></div></div><div class="field"><div class="label">Paid</div><div class="value"><?=saas_h($currency)?> <?=number_format($paid,2)?></div></div><div class="field"><div class="label">Due</div><div class="value"><?=($due<=0?'PAID':saas_h($currency).' '.number_format($due,2))?></div></div><div class="field"><div class="label">Ticket No</div><div class="value"><?=saas_h($ticket['ticket_number'])?></div></div></div></div><div class="qr"><img src="<?=saas_h($qrUrl)?>" alt="Ticket QR"></div></section></main></body></html>